import { useCallback, useEffect, useState } from 'react'
import { db } from '@/db/db'
import { reminderQueue, type PlannedEvent, type QuietHours } from './schedule'

/**
 * Local reminders (CAL-04).
 *
 * No push service, no server, no subscription endpoint — TemuDua must keep
 * working in airplane mode, and a push service would mean shipping calendar
 * metadata to somebody else's machine. The consequence is honest and stated in
 * the UI: a reminder fires while the app is open, or the next time it is opened
 * inside the grace window. It cannot wake a closed browser.
 *
 * Permission is never requested on load. `ask()` is only called from the click
 * that attaches the first reminder, which is the one moment the user has
 * actually asked for notifications.
 */

const PREFS_KEY = 'calendar2.reminders'
const FIRED_KEY = 'calendar2.reminders.fired'
/** Enough to stop a re-show after a reload; small enough to stay cheap. */
const FIRED_MEMORY = 50

export interface ReminderPrefs {
  enabled: boolean
  quiet: QuietHours
}

export const DEFAULT_PREFS: ReminderPrefs = {
  enabled: true,
  quiet: { from: '22:00', to: '07:00' },
}

export type PermissionState = NotificationPermission | 'unsupported'

export function permissionState(): PermissionState {
  if (typeof Notification === 'undefined') return 'unsupported'
  return Notification.permission
}

export async function ask(): Promise<PermissionState> {
  if (typeof Notification === 'undefined') return 'unsupported'
  if (Notification.permission !== 'default') return Notification.permission
  return await Notification.requestPermission()
}

/**
 * Body text is generic on purpose. A notification lands on a lock screen that
 * anybody in the room can read, so it never carries the event title, the time,
 * the place, or who it is with — blueprint 05: no sensitive content off-app.
 */
export async function notify(title: string, body: string, tag: string): Promise<void> {
  if (permissionState() !== 'granted') return
  const options: NotificationOptions = { body, tag, icon: 'icons/icon-192.png' }
  const reg = await navigator.serviceWorker?.getRegistration()
  if (reg) await reg.showNotification(title, options)
  else new Notification(title, options)
}

export async function loadPrefs(): Promise<ReminderPrefs> {
  const row = await db.settings.get(PREFS_KEY)
  return { ...DEFAULT_PREFS, ...((row?.value as Partial<ReminderPrefs> | undefined) ?? {}) }
}

export async function savePrefs(prefs: ReminderPrefs): Promise<void> {
  await db.settings.put({ key: PREFS_KEY, value: prefs })
}

async function firedKeys(): Promise<string[]> {
  return ((await db.settings.get(FIRED_KEY))?.value as string[] | undefined) ?? []
}

async function markFired(key: string): Promise<void> {
  const next = [...(await firedKeys()), key].slice(-FIRED_MEMORY)
  await db.settings.put({ key: FIRED_KEY, value: next })
}

/** Prefs live in `settings`, which is config, not envelope-wrapped user data. */
export function useReminderPrefs(): [ReminderPrefs, (next: ReminderPrefs) => Promise<void>] {
  const [prefs, setPrefs] = useState<ReminderPrefs>(DEFAULT_PREFS)
  useEffect(() => {
    void loadPrefs().then(setPrefs)
  }, [])
  const update = useCallback(async (next: ReminderPrefs) => {
    setPrefs(next)
    await savePrefs(next)
  }, [])
  return [prefs, update]
}

/**
 * One timer, re-armed after every fire and on every data change.
 *
 * ponytail: a single `setTimeout` for the next reminder rather than one per
 * event — the queue is recomputed from scratch each time anyway, so N timers
 * would buy nothing and leak on every re-render.
 */
export function useReminderScheduler(
  events: PlannedEvent[] | undefined,
  prefs: ReminderPrefs,
  copy: { title: string; body: string },
): void {
  useEffect(() => {
    if (!prefs.enabled || !events?.length) return
    let timer: ReturnType<typeof setTimeout> | undefined
    let cancelled = false

    async function tick(): Promise<void> {
      if (cancelled) return
      const queue = reminderQueue(events ?? [], prefs.quiet, new Date())
      const already = await firedKeys()
      for (const due of queue.overdue) {
        if (already.includes(due.key)) continue
        await notify(copy.title, copy.body, due.key)
        await markFired(due.key)
      }
      if (cancelled || !queue.next) return
      // Capped so a reminder six months out does not sit on one huge timer,
      // which browsers throttle and 32-bit setTimeout overflows outright.
      const wait = Math.min(queue.next.at.getTime() - Date.now() + 500, 60 * 60_000)
      timer = setTimeout(() => void tick(), Math.max(wait, 1000))
    }

    void tick()
    return () => {
      cancelled = true
      if (timer) clearTimeout(timer)
    }
  }, [events, prefs, copy.title, copy.body])
}
