import { addDays, parseISO } from 'date-fns'
import type { CalendarEvent, EventType, Visibility } from '@/types/domain'

/**
 * Scheduling maths for the couple views (CAL-01..04).
 *
 * Everything here is pure and returns *keys and numbers*, never copy — the same
 * rule the rest of the codebase follows, so the conflict wording can change
 * without touching the logic or its tests. date-fns is used for day arithmetic
 * only; anything a human reads is formatted in the component through
 * `@/i18n/format`.
 */

// ---------------------------------------------------------------------------
// Types this feature adds on top of the stored row
// ---------------------------------------------------------------------------

export type ProposalStatus = 'pending' | 'accepted' | 'declined' | 'countered'

export interface Proposal {
  byProfileId: string
  toProfileId: string
  status: ProposalStatus
  note?: string
  /** Filled when the receiver suggests a different time instead of saying no. */
  counterDate?: string
  counterTime?: string
  respondedAt?: string
}

/**
 * A stored `events` row plus the fields this feature needs.
 *
 * `CalendarEvent` lives in `src/types/domain.ts`, which this feature is not
 * allowed to edit, so the extra fields are declared structurally here. Dexie
 * stores whatever object it is given and `backup.ts` copies rows verbatim, so
 * they survive a save, a reload, and an export/restore round trip. If these
 * ever earn an index they belong in domain.ts under a new `version(n)` block.
 */
export type PlannedEvent = CalendarEvent & {
  /** HH:mm. Absent means "assume DEFAULT_DURATION_MIN". */
  endTime?: string
  /** Free text the user typed. Never geocoded — TemuDua has no map service. */
  place?: string
  proposal?: Proposal
  /** Minutes before the start. Absent means no reminder. */
  remindMinutes?: number
}

// ---------------------------------------------------------------------------
// Time-of-day helpers. Minutes-since-midnight is the unit everywhere below.
// ---------------------------------------------------------------------------

export const DEFAULT_DURATION_MIN = 60
/** Below this, two back-to-back items in different places are worth mentioning. */
export const MIN_TRAVEL_MIN = 30
/** An "a lot on today" hint, not a limit and not a judgement. */
export const BUSY_DAY_ITEMS = 5
/** Items with no clock time get their reminder here rather than at midnight. */
export const ALL_DAY_REMIND_AT = '08:00'

export function toMin(hhmm: string): number {
  const [h = '0', m = '0'] = hhmm.split(':')
  return Math.max(0, Math.min(24 * 60, Number(h) * 60 + Number(m)))
}

export function fromMin(min: number): string {
  const clamped = Math.max(0, Math.min(24 * 60, Math.round(min)))
  const h = Math.floor(clamped / 60)
  const m = clamped % 60
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`
}

/** Local Date for a yyyy-MM-dd + HH:mm pair. Local, because reminders are local. */
export function at(dateISO: string, hhmm: string): Date {
  const d = parseISO(dateISO)
  d.setHours(Math.floor(toMin(hhmm) / 60), toMin(hhmm) % 60, 0, 0)
  return d
}

// ---------------------------------------------------------------------------
// Busy blocks and free slots
// ---------------------------------------------------------------------------

export interface Block {
  id: string
  title: string
  start: number
  end: number
  place?: string
  ownerProfileId: string
  type: EventType
}

/**
 * Timed events on one day, as sorted blocks.
 *
 * An event with no clock time is deliberately *not* a block: "ulang tahun Ibu"
 * should not eat the whole day when the finder looks for two free hours. The UI
 * says so out loud rather than guessing a duration.
 */
export function blocksForDay(events: PlannedEvent[]): Block[] {
  return events
    .filter((e) => !!e.time)
    .map((e) => {
      const start = toMin(e.time!)
      const end = e.endTime ? Math.max(start + 1, toMin(e.endTime)) : start + DEFAULT_DURATION_MIN
      return {
        id: e.id,
        title: e.title,
        start,
        end,
        ...(e.place ? { place: e.place } : {}),
        ownerProfileId: e.ownerProfileId,
        type: e.type,
      }
    })
    .sort((a, b) => a.start - b.start || a.end - b.end)
}

export interface Span {
  start: number
  end: number
}

/** Overlapping or touching blocks collapsed into one span. */
export function mergeSpans(blocks: Span[]): Span[] {
  const sorted = [...blocks].sort((a, b) => a.start - b.start)
  const out: Span[] = []
  for (const b of sorted) {
    const last = out[out.length - 1]
    if (last && b.start <= last.end) last.end = Math.max(last.end, b.end)
    else out.push({ start: b.start, end: b.end })
  }
  return out
}

/** Gaps of at least `durationMin` between `dayStart` and `dayEnd`. */
export function freeSlots(
  blocks: Span[],
  durationMin: number,
  dayStart: number,
  dayEnd: number,
): Span[] {
  if (durationMin <= 0 || dayEnd - dayStart < durationMin) return []
  const out: Span[] = []
  let cursor = dayStart
  for (const busy of mergeSpans(blocks)) {
    if (busy.end <= cursor) continue
    if (busy.start >= dayEnd) break
    if (busy.start - cursor >= durationMin) out.push({ start: cursor, end: busy.start })
    cursor = Math.max(cursor, busy.end)
  }
  if (dayEnd - cursor >= durationMin) out.push({ start: cursor, end: dayEnd })
  return out
}

export interface DayEvents {
  date: string
  events: PlannedEvent[]
}

export interface FreeSlot {
  date: string
  start: number
  end: number
}

/**
 * "Cari waktu kosong 2 jam minggu ini" — free for *both* people, because the
 * caller passes the union of what the two of them can see. What the viewer is
 * not allowed to read never reaches this function, so a private event silently
 * fails to block the slot. That is the privacy model working as designed, and
 * the screen says it in plain words.
 */
export function findAvailability(
  days: DayEvents[],
  durationMin: number,
  dayStart: number,
  dayEnd: number,
  /** Slots ending before this are dropped; pass a `{date, min}` for "now". */
  notBefore?: { date: string; min: number },
): FreeSlot[] {
  const out: FreeSlot[] = []
  for (const day of days) {
    if (notBefore && day.date < notBefore.date) continue
    const start =
      notBefore && day.date === notBefore.date ? Math.max(dayStart, notBefore.min) : dayStart
    for (const slot of freeSlots(blocksForDay(day.events), durationMin, start, dayEnd)) {
      out.push({ date: day.date, start: slot.start, end: slot.end })
    }
  }
  return out
}

// ---------------------------------------------------------------------------
// Conflicts
//
// Every code below describes the *calendar*, never a person. There is no
// "you overcommitted" and no per-partner tally — see CLAUDE.md.
// ---------------------------------------------------------------------------

export type ConflictCode = 'overlap' | 'travel' | 'packed' | 'noSharedTime'

export interface Conflict {
  code: ConflictCode
  /** Blocks involved, so the UI can name them without re-deriving anything. */
  titles: string[]
  minutes?: number
  count?: number
}

/** Conflicts inside one person's day. Two people being busy at once is not one. */
export function dayConflicts(blocks: Block[]): Conflict[] {
  const out: Conflict[] = []
  const sorted = [...blocks].sort((a, b) => a.start - b.start)

  for (let i = 0; i < sorted.length - 1; i++) {
    const a = sorted[i]!
    const b = sorted[i + 1]!
    if (b.start < a.end) {
      out.push({ code: 'overlap', titles: [a.title, b.title] })
      continue
    }
    const gap = b.start - a.end
    // Only when both sides actually named a place, and the names differ. The app
    // has no routing data, so it reports the gap and refuses to estimate travel.
    if (a.place && b.place && a.place !== b.place && gap < MIN_TRAVEL_MIN) {
      out.push({ code: 'travel', titles: [a.title, b.title], minutes: gap })
    }
  }

  if (sorted.length >= BUSY_DAY_ITEMS) {
    out.push({ code: 'packed', titles: [], count: sorted.length })
  }
  return out
}

const SHARED_VISIBILITY: ReadonlySet<Visibility> = new Set<Visibility>(['shared', 'both_partners'])

/**
 * One week-level observation: no time the two of them put on the calendar
 * together. Phrased as a fact about the week, never as a shortfall.
 */
export function weekConflicts(events: PlannedEvent[]): Conflict[] {
  const together = events.some(
    (e) =>
      SHARED_VISIBILITY.has(e.visibility) &&
      (e.type === 'date' || e.coOwnerProfileIds.length > 0) &&
      e.proposal?.status !== 'declined',
  )
  return together ? [] : [{ code: 'noSharedTime', titles: [] }]
}

// ---------------------------------------------------------------------------
// Reminders
// ---------------------------------------------------------------------------

export interface QuietHours {
  /** HH:mm. `from === to` means "no quiet hours". */
  from: string
  to: string
}

export function inQuietHours(d: Date, q: QuietHours): boolean {
  const from = toMin(q.from)
  const to = toMin(q.to)
  if (from === to) return false
  const now = d.getHours() * 60 + d.getMinutes()
  // A window that wraps midnight (22:00 → 07:00) is the normal case, so it is
  // handled first rather than as an afterthought.
  return from > to ? now >= from || now < to : now >= from && now < to
}

/** The first moment at or after `d` that is outside quiet hours. */
export function shiftOutOfQuiet(d: Date, q: QuietHours): Date {
  if (!inQuietHours(d, q)) return d
  const to = toMin(q.to)
  const out = new Date(d)
  out.setHours(Math.floor(to / 60), to % 60, 0, 0)
  if (out <= d) out.setTime(addDays(out, 1).getTime())
  return out
}

export interface PendingReminder {
  /** Stable per event *and* per date, so a moved event reminds again. */
  key: string
  eventId: string
  at: Date
}

export function reminderAt(event: PlannedEvent, quiet: QuietHours): Date | null {
  if (event.remindMinutes === undefined) return null
  const start = at(event.date, event.time ?? ALL_DAY_REMIND_AT)
  const fire = new Date(start.getTime() - event.remindMinutes * 60_000)
  return shiftOutOfQuiet(fire, quiet)
}

export interface ReminderQueue {
  /** Already due and not yet shown. */
  overdue: PendingReminder[]
  /** Soonest future one, so the caller needs a single timer. */
  next?: PendingReminder
}

/**
 * ponytail: reminders fire off the event's own stored date only — a recurring
 * event reminds for its first occurrence, not every repeat. Expanding the rule
 * here would mean holding a live occurrence list in a background timer; if
 * repeat reminders are wanted, feed `occurrencesInRange()` output in as
 * synthetic events instead of complicating this function.
 */
export function reminderQueue(
  events: PlannedEvent[],
  quiet: QuietHours,
  now: Date,
  /** How stale a missed reminder may be before it is dropped instead of shown. */
  graceMin = 120,
): ReminderQueue {
  const overdue: PendingReminder[] = []
  let next: PendingReminder | undefined

  for (const event of events) {
    const when = reminderAt(event, quiet)
    if (!when) continue
    const pending: PendingReminder = {
      key: `${event.id}@${event.date}@${event.remindMinutes}`,
      eventId: event.id,
      at: when,
    }
    if (when.getTime() <= now.getTime()) {
      if (now.getTime() - when.getTime() <= graceMin * 60_000) overdue.push(pending)
    } else if (!next || when < next.at) {
      next = pending
    }
  }
  return next ? { overdue, next } : { overdue }
}
