/**
 * Couple calendar (CAL-01..04): side-by-side day, week, agenda, proposals and
 * local reminders.
 *
 * It is mounted by `Calendar.tsx` as a set of tabs next to the month grid,
 * which stays exactly as it was — the month view is the one people already
 * know, so it remains the default. Every view here reads through `useOwned`,
 * so a private event on one side simply never reaches the other side's column.
 */

/**
 * Type-only export on purpose: a value export from a file whose default is a
 * component breaks React Fast Refresh, and remounting the calendar on every
 * save loses whatever tab you were looking at. The tab list lives in
 * `Calendar.tsx`, which is where it is rendered.
 */
export type PlannerView = 'berdua' | 'minggu' | 'agenda' | 'usulan' | 'pengingat'

const REMINDER_CHOICES = [
  { minutes: undefined, key: 'calendar2.rem.none' },
  { minutes: 10, key: 'calendar2.rem.m10' },
  { minutes: 30, key: 'calendar2.rem.m30' },
  { minutes: 60, key: 'calendar2.rem.h1' },
  { minutes: 1440, key: 'calendar2.rem.d1' },
] as const

const TYPE_ICON: Record<string, IconName> = {
  date: 'date',
  task: 'tasks',
  bill: 'money',
  family: 'family',
  me_time: 'self',
  health: 'health',
  celebration: 'memories',
  private: 'private',
}

const iso = (d: Date) => format(d, 'yyyy-MM-dd')
const todayISO = () => iso(new Date())

/** Occurrences flattened back into events that carry the date they land on. */
function eventsByDate(events: PlannedEvent[], from: string, to: string): Map<string, PlannedEvent[]> {
  const out = new Map<string, PlannedEvent[]>()
  for (const [date, list] of occurrencesInRange(events, from, to)) {
    out.set(
      date,
      list
        .map((o) => ({ ...(o.event as PlannedEvent), date: o.date }))
        .sort((a, b) => (a.time ?? '99:99').localeCompare(b.time ?? '99:99')),
    )
  }
  return out
}

/** A proposal that has not been agreed is still only its author's plan. */
function isBinding(e: PlannedEvent): boolean {
  return !e.proposal || e.proposal.status === 'accepted'
}

export default function CalendarPlanner({
  view = 'berdua',
  date,
  onDate,
}: {
  view?: PlannerView
  date?: string
  onDate?: (iso: string) => void
}) {
  const t = useT()
  const { locale } = useI18n()
  const { profile, partner } = useSession()
  const me = profile?.id
  const [ownDate, setOwnDate] = useState(todayISO)
  const selected = date ?? ownDate
  const setSelected = onDate ?? setOwnDate

  const events = useOwned<PlannedEvent>('events', me)
  const [prefs, setPrefs] = useReminderPrefs()

  // Only the rows this profile owns or co-owns are worth a notification — a
  // reminder attached to somebody else's event is their business, not yours.
  const mine = useMemo(
    () =>
      (events ?? []).filter(
        (e) => e.ownerProfileId === me || e.coOwnerProfileIds.includes(me ?? ''),
      ),
    [events, me],
  )
  useReminderScheduler(mine, prefs, {
    title: t('calendar2.rem.notifTitle'),
    body: t('calendar2.rem.notifBody'),
  })

  if (!profile || !me) return null
  if (!events) return null

  const shared = { t, locale, me, partner, events, selected, setSelected }

  return (
    <div className="stack">
      {view === 'berdua' && <CoupleDay {...shared} />}
      {view === 'minggu' && <WeekView {...shared} />}
      {view === 'agenda' && <AgendaView {...shared} />}
      {view === 'usulan' && <Proposals {...shared} />}
      {view === 'pengingat' && (
        <Reminders {...shared} prefs={prefs} onPrefs={(p) => void setPrefs(p)} />
      )}
    </div>
  )
}

interface ViewProps {
  t: TFunction
  locale: Locale
  me: string
  partner: Profile | null
  events: PlannedEvent[]
  selected: string
  setSelected: (iso: string) => void
}

// ---------------------------------------------------------------------------
// Side-by-side day
// ---------------------------------------------------------------------------

function CoupleDay({ t, locale, me, partner, events, selected, setSelected }: ViewProps) {
  const byDate = useMemo(() => eventsByDate(events, selected, selected), [events, selected])
  const day = byDate.get(selected) ?? []
  // An agreed event is co-owned, so it takes up a slot in *both* columns. Owner
  // alone would hide it from the person who accepted it.
  const belongsTo = (e: PlannedEvent, id: string) =>
    e.ownerProfileId === id || e.coOwnerProfileIds.includes(id)
  const mine = day.filter((e) => belongsTo(e, me))
  const theirs = partner ? day.filter((e) => belongsTo(e, partner.id)) : []

  const week = useMemo(
    () =>
      eventsByDate(
        events,
        iso(startOfWeek(parseISO(selected), { weekStartsOn: 1 })),
        iso(endOfWeek(parseISO(selected), { weekStartsOn: 1 })),
      ),
    [events, selected],
  )

  // Each column is checked on its own: two people being busy at the same time
  // is not a clash, it is Tuesday.
  const conflicts: Conflict[] = [
    ...dayConflicts(blocksForDay(mine.filter(isBinding))),
    ...dayConflicts(blocksForDay(theirs.filter(isBinding))),
    ...weekConflicts([...week.values()].flat().filter(isBinding)),
  ]

  return (
    <>
      <Card>
        <div className="row row--between">
          <button
            className="btn btn--ghost btn--sm btn--icon"
            onClick={() => setSelected(iso(addDays(parseISO(selected), -1)))}
          >
            <Icon name="chevron-left" size={18} label={t('calendar2.day.prev')} />
          </button>
          <div className="stack stack--tight" style={{ textAlign: 'center' }}>
            <strong aria-live="polite">{fmtDate(selected, 'EEEE, d MMMM yyyy', locale)}</strong>
            <button className="btn btn--ghost btn--sm" onClick={() => setSelected(todayISO())}>
              {t('calendar2.day.today')}
            </button>
          </div>
          <button
            className="btn btn--ghost btn--sm btn--icon"
            onClick={() => setSelected(iso(addDays(parseISO(selected), 1)))}
          >
            <Icon name="chevron-right" size={18} label={t('calendar2.day.next')} />
          </button>
        </div>

        <div className="cal2__cols">
          <DayColumn t={t} title={t('calendar2.day.mine')} icon="self" events={mine} />
          <DayColumn
            t={t}
            title={partner?.displayName ?? t('calendar2.day.partner')}
            icon="shared"
            events={theirs}
            empty={partner ? undefined : t('calendar2.day.noPartner')}
          />
        </div>
        <p className="disclaimer">{t('calendar2.day.privateNote')}</p>
      </Card>

      <ConflictCard t={t} conflicts={conflicts} />
    </>
  )
}

function DayColumn({
  t,
  title,
  icon,
  events,
  empty,
}: {
  t: TFunction
  title: string
  icon: IconName
  events: PlannedEvent[]
  empty?: string
}) {
  return (
    <section className="cal2__col stack stack--tight" aria-label={title}>
      <h3 className="cal2__colhead">
        <Icon name={icon} size={16} />
        {title}
      </h3>
      {events.length === 0 ? (
        <p className="card__hint">{empty ?? t('calendar2.day.empty')}</p>
      ) : (
        <ul className="list">
          {events.map((e) => (
            <li key={`${e.id}-${e.date}`} className="list__item cal2__item">
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14 }}>{e.title}</strong>
                <span className="card__hint">
                  {e.time ?? t('calendar2.allDay')}
                  {e.endTime ? ` · ${t('calendar2.untilTime', { time: e.endTime })}` : ''}
                  {e.place ? ` · ${t('calendar2.atPlace', { place: e.place })}` : ''}
                </span>
                {e.proposal && e.proposal.status !== 'accepted' && (
                  <span className="chip chip--yellow">
                    <Icon name="consent" size={14} />
                    {t(`calendar2.prop.status.${e.proposal.status}` as const)}
                  </span>
                )}
              </span>
              <Icon name={TYPE_ICON[e.type] ?? 'calendar'} size={18} />
            </li>
          ))}
        </ul>
      )}
    </section>
  )
}

function ConflictCard({ t, conflicts }: { t: TFunction; conflicts: Conflict[] }) {
  const hasTravel = conflicts.some((c) => c.code === 'travel')
  return (
    <Card title={t('calendar2.conflict.title')} icon="info">
      {conflicts.length === 0 ? (
        <p className="card__hint">{t('calendar2.conflict.none')}</p>
      ) : (
        <ul className="list">
          {conflicts.map((c, i) => (
            <li key={`${c.code}-${i}`} className="list__item">
              <Icon name="info" size={18} />
              <span className="grow">{conflictText(t, c)}</span>
            </li>
          ))}
        </ul>
      )}
      {hasTravel && <p className="disclaimer">{t('calendar2.conflict.travelHint')}</p>}
    </Card>
  )
}

/** Codes become copy here and nowhere else, so `schedule.ts` stays text-free. */
function conflictText(t: TFunction, c: Conflict): string {
  if (c.code === 'overlap') return t('calendar2.conflict.overlap', { a: c.titles[0] ?? '', b: c.titles[1] ?? '' })
  if (c.code === 'travel')
    return t('calendar2.conflict.travel', {
      a: c.titles[0] ?? '',
      b: c.titles[1] ?? '',
      minutes: c.minutes ?? 0,
    })
  if (c.code === 'packed') return t('calendar2.conflict.packed', { n: c.count ?? 0 })
  return t('calendar2.conflict.noSharedTime')
}

// ---------------------------------------------------------------------------
// Week
// ---------------------------------------------------------------------------

function WeekView({ t, locale, me, events, selected, setSelected }: ViewProps) {
  const start = startOfWeek(parseISO(selected), { weekStartsOn: 1 })
  const end = endOfWeek(parseISO(selected), { weekStartsOn: 1 })
  const byDate = useMemo(() => eventsByDate(events, iso(start), iso(end)), [events, selected])
  const days = eachDayOfInterval({ start, end })

  return (
    <Card>
      <div className="row row--between">
        <button
          className="btn btn--ghost btn--sm btn--icon"
          onClick={() => setSelected(iso(addWeeks(start, -1)))}
        >
          <Icon name="chevron-left" size={18} label={t('calendar2.week.prev')} />
        </button>
        <strong aria-live="polite">
          {fmtDate(iso(start), 'd MMM', locale)} – {fmtDate(iso(end), 'd MMM yyyy', locale)}
        </strong>
        <button
          className="btn btn--ghost btn--sm btn--icon"
          onClick={() => setSelected(iso(addWeeks(start, 1)))}
        >
          <Icon name="chevron-right" size={18} label={t('calendar2.week.next')} />
        </button>
      </div>

      <ul className="list">
        {days.map((d) => {
          const key = iso(d)
          const list = byDate.get(key) ?? []
          return (
            <li key={key} className="list__item cal2__weekrow">
              <button
                className="btn btn--ghost btn--sm cal2__weekday"
                onClick={() => setSelected(key)}
              >
                {fmtDate(key, 'EEE d', locale)}
              </button>
              <span className="grow cal2__chips">
                {list.length === 0 && <span className="card__hint">{t('calendar2.week.free')}</span>}
                {list.slice(0, 3).map((e) => (
                  <span
                    key={`${e.id}-${e.date}`}
                    className={`chip ${e.ownerProfileId === me ? 'chip--blue' : 'chip--lavender'}`}
                  >
                    {e.time ? `${e.time} ` : ''}
                    {e.title}
                  </span>
                ))}
                {list.length > 3 && (
                  <span className="chip">{t('calendar2.week.more', { n: list.length - 3 })}</span>
                )}
              </span>
            </li>
          )
        })}
      </ul>
    </Card>
  )
}

