function Reminders({
  t,
  locale,
  me,
  events,
  prefs,
  onPrefs,
}: ViewProps & {
  prefs: { enabled: boolean; quiet: { from: string; to: string } }
  onPrefs: (p: { enabled: boolean; quiet: { from: string; to: string } }) => void
}) {
  const [perm, setPerm] = useState<PermissionState>(() => permissionState())
  const from = todayISO()
  const to = iso(addDays(new Date(), 30))

  // Only rows this profile owns: a reminder is stored on the event, so setting
  // one on a partner-owned row would quietly change their record too.
  const upcoming = events
    .filter((e) => e.ownerProfileId === me && e.date >= from && e.date <= to)
    .sort((a, b) => a.date.localeCompare(b.date) || (a.time ?? '').localeCompare(b.time ?? ''))

  /** The permission prompt happens here and only here — after a real reminder. */
  async function setReminder(event: PlannedEvent, minutes: number | undefined) {
    await patch('events', event.id, { remindMinutes: minutes })
    if (minutes !== undefined && permissionState() === 'default') setPerm(await ask())
  }

  return (
    <>
      <Card title={t('calendar2.rem.title')} icon="consent" hint={t('calendar2.rem.honest')}>
        <label className="row" style={{ gap: 'var(--space-2)' }}>
          <input
            type="checkbox"
            checked={prefs.enabled}
            onChange={(e) => onPrefs({ ...prefs, enabled: e.target.checked })}
          />
          <span>{t('calendar2.rem.enabled')}</span>
        </label>

        <div className="cal2__cols">
          <Field label={t('calendar2.rem.quietFrom')}>
            {(p) => (
              <input
                {...p}
                type="time"
                value={prefs.quiet.from}
                onChange={(e) => onPrefs({ ...prefs, quiet: { ...prefs.quiet, from: e.target.value } })}
              />
            )}
          </Field>
          <Field label={t('calendar2.rem.quietTo')}>
            {(p) => (
              <input
                {...p}
                type="time"
                value={prefs.quiet.to}
                onChange={(e) => onPrefs({ ...prefs, quiet: { ...prefs.quiet, to: e.target.value } })}
              />
            )}
          </Field>
        </div>
        <p className="card__hint">{t('calendar2.rem.quietHint')}</p>

        {perm === 'granted' && <p className="banner">{t('calendar2.rem.granted')}</p>}
        {perm === 'denied' && <p className="banner banner--warn">{t('calendar2.rem.denied')}</p>}
        {perm === 'unsupported' && <p className="banner banner--warn">{t('calendar2.rem.unsupported')}</p>}
        {perm === 'default' && upcoming.some((e) => e.remindMinutes !== undefined) && (
          <button className="btn btn--soft" onClick={() => void ask().then(setPerm)}>
            <Icon name="consent" size={16} /> {t('calendar2.rem.ask')}
          </button>
        )}
        <p className="disclaimer">{t('calendar2.rem.privacyNote')}</p>
      </Card>

      <Card title={t('calendar2.rem.listTitle')} icon="calendar">
        {upcoming.length === 0 ? (
          <EmptyState
            icon="calendar"
            title={t('calendar2.rem.empty')}
            hint={t('calendar2.rem.emptyHint')}
          />
        ) : (
          <ul className="list">
            {upcoming.map((e) => (
              <li key={e.id} className="list__item cal2__reminder">
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{e.title}</strong>
                  <span className="card__hint">
                    {whenLabel(e.date, t, locale)} · {e.time ?? t('calendar2.allDay')}
                  </span>
                </span>
                <label className="cal2__remindpick">
                  <span className="visually-hidden">{`${t('calendar2.rem.pick')}: ${e.title}`}</span>
                  <select
                    value={e.remindMinutes ?? ''}
                    onChange={(ev) =>
                      void setReminder(e, ev.target.value === '' ? undefined : Number(ev.target.value))
                    }
                  >
                    {REMINDER_CHOICES.map((c) => (
                      <option key={c.key} value={c.minutes ?? ''}>
                        {t(c.key)}
                      </option>
                    ))}
                  </select>
                </label>
              </li>
            ))}
          </ul>
        )}
        <p className="card__hint">{t('calendar2.rem.allDayAt', { time: ALL_DAY_REMIND_AT })}</p>
        <p className="card__hint">{t('calendar2.rem.askHint')}</p>
      </Card>
    </>
  )
}
